/**
 Decodes CSS escape sequences (backslash escapes and hex code points) in {@code in}.
 @throws IllegalArgumentException on an incomplete escape sequence (a trailing backslash)
 */
public static String unescapeCss(String in) {
    if (in.indexOf(Esc) == -1) return in;
    StringBuilder out = StringUtil.borrowBuilder();
    TokenQueue q = new TokenQueue(in);
    try {
        while (!q.isEmpty()) {
            char c = q.consume();
            if (c == Esc) {
                if (q.isEmpty()) throw new IllegalArgumentException("Invalid escape sequence: input ends after escape character");
                q.consumeCssEscapeSequenceInto(out);
            } else {
                out.append(c);
            }
        }
    } finally {
        q.close();
    }
    return StringUtil.releaseBuilder(out);
}
