private Evaluator.CaseSensitivity consumeCaseModifier(TokenQueue cq) {
    cq.consumeWhitespace();
    if (cq.isEmpty()) return Evaluator.CaseSensitivity.INSENSITIVE;
    char m = cq.consume();
    final Evaluator.CaseSensitivity sensitivity;
    if (m == 'i' || m == 'I') sensitivity = Evaluator.CaseSensitivity.INSENSITIVE;
    else if (m == 's' || m == 'S') sensitivity = Evaluator.CaseSensitivity.SENSITIVE;
    else throw new Selector.SelectorParseException(
        "Could not parse attribute query '%s': unexpected token at '%s'", query, m + cq.remainder());
    cq.consumeWhitespace();
    if (!cq.isEmpty())
        throw new Selector.SelectorParseException(
            "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
    return sensitivity;
}
