        String got = sb.length() == 0 ? "" : sb.substring(0, sb.length()-1);
        System.out.println((got.equals(expect) ? "OK  " : "FAIL") + " " + q + " -> [" + got + "] expected [" + expect + "]");
    }
    static void err(String q) {
        try { doc.select(q); System.out.println("FAIL (no throw) " + q); }
        catch (Exception e) { System.out.println("OK   throws " + q + " -> " + e.getClass().getSimpleName() + ": " + e.getMessage()); }
