import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class T2 {
    static Document doc = Jsoup.parse("<a id=a data-v=\"A B\"></a><a id=b data-v=\"a b\"></a><a id=c data-v=\"x&quot;y\"></a><a id=d data-v=\"\"></a><a id=f data-v=\"Alpha\"></a><i id=e></i>");
    static void check(String q, String expect) {
        Elements els = doc.body().select("body > " + q);
        StringBuilder sb = new StringBuilder();
        els.forEach(e -> sb.append(e.id()).append(','));
        String got = sb.length() == 0 ? "" : sb.substring(0, sb.length()-1);
        System.out.println((got.equals(expect) ? "OK  " : "FAIL") + " " + q + " -> [" + got + "] expected [" + expect + "]");
    }
    public static void main(String[] a) {
        check("[data-v~=^a]", "b");              // regex semantics unchanged (case-sensitive regex)
        check("[data-v~=^(?i)a]", "a,b,f");      // regex with embedded flag
        check("[data-v~=A B]", "a");             // regex containing a space still works
        check("[data-v='' i]", "d");
        check("[data-v=\"A B\" s]", "a");
        check("[data-v^=A]", "a,f");
        check("[data-v*=B]", "a");
        check("[data-v$=b]", "b");
        check("[data-v!=a b s]", "a,c,d,f,e");
        check("[^data-v]", "a,b,c,d,f");
        check("[*]", "a,b,c,d,f,e");
        check("[data-v]", "a,b,c,d,f");
        // duplicates / document order
        Elements els = doc.select("[data-v], [data-v]");
        System.out.println((els.size() == 5 ? "OK  " : "FAIL") + " dedupe [data-v],[data-v] -> " + els.size());
    }
}
EOF
javac -cp target/classes -d /tmp/attrtest /tmp/attrtest/T2.java && java -cp target/classes:/tmp/attrtest T2

